def merge(ranges):
    result = []
    for start, end in sorted((min(a,b),max(a,b)) for a,b in ranges):
        if result and start <= result[-1][1] + 1:
            result[-1] = (result[-1][0], max(end,result[-1][1]))
        else:
            result.append((start,end))
    return result

